def calc(expr: str) -> int | str:
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        elif c in "+-*/%^()":
            tokens.append(c)
            i += 1
        else:
            i += 1

    pos = 0

    def parse_expr():
        val = parse_term()
        nonlocal pos
        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            rhs = parse_term()
            if op == '+':
                val = val + rhs
            else:
                val = val - rhs
        return val

    def parse_term():
        nonlocal pos
        val = parse_unary()
        while pos < len(tokens) and tokens[pos] in ('*', '/', '%'):
            op = tokens[pos]
            pos += 1
            rhs = parse_unary()
            if op == '*':
                val = val * rhs
            elif op == '/':
                if rhs == 0:
                    raise ZeroDivisionError
                # truncate towards zero
                if (val >= 0 and rhs > 0) or (val <= 0 and rhs < 0):
                    val = abs(val) // abs(rhs)
                else:
                    val = -(abs(val) // abs(rhs))
            elif op == '%':
                if rhs == 0:
                    raise ZeroDivisionError
                # a % b = a - b * (a / b)
                if (val >= 0 and rhs > 0) or (val <= 0 and rhs < 0):
                    q = abs(val) // abs(rhs)
                else:
                    q = -(abs(val) // abs(rhs))
                val = val - rhs * q
        return val

    def parse_unary():
        nonlocal pos
        if pos < len(tokens) and tokens[pos] == '-':
            pos += 1
            return -parse_unary()
        if pos < len(tokens) and tokens[pos] == '+':
            pos += 1
            return parse_unary()
        return parse_power()

    def parse_power():
        nonlocal pos
        base = parse_primary()
        if pos < len(tokens) and tokens[pos] == '^':
            pos += 1
            exp = parse_unary()
            if exp < 0:
                raise ValueError("Negative exponent")
            return pow(base, exp)
        return base

    def parse_primary():
        nonlocal pos
        token = tokens[pos]
        pos += 1
        if isinstance(token, int):
            return token
        if token == '(':
            val = parse_expr()
            pos += 1  # consume ')'
            return val
        raise ValueError("Invalid syntax")

    try:
        return parse_expr()
    except (ZeroDivisionError, ValueError):
        return "error"
